import "./index.less"

class StoriesShare {
    constructor() {
        this.pageShareUrl = this.getShareUrl()
        this.insShareSuccessText = 'Copy successfully,open Instagram to post!'

        document.querySelectorAll('[data-type]').forEach(it => {
            const type = it.dataset.type
            it.onclick = () => this.socialShareFunc(type)
        })
    }
    
    // 分享链接
    getShareUrl() {
        const href = window.location.href;
        const pathname = window.location.pathname
        let country = window.Shopify.country.toLowerCase();
        if (country === "gb") country = "uk";
        const arr = ["us", "jp"];
        const com = country === "jp" ? "jp" : "com";
        let url = `https://demo-us.jackery.com${pathname}`;
        if (href.indexOf("demo") === -1) {
            url = `https://${arr.includes(country) ? "www" : country}.jackery.${com}${pathname}`;
        }
        return url;
    }
    socialShareFunc(type) {
        let shareUrl = this.getSocialShareAPI(type);

        if (type !== 'Instagram') {
            this.openWindows(shareUrl);
        } else {
            this.copyFunc(this.pageShareUrl);
            pushSuccessMessage(this.insShareSuccessText);
        }
    }
    openWindows(url) {
        window.open(
            url,
            "单独窗口",
            "height=300,width=600,top=30,left=20,toolbar=no,menubar=no,scrollbars=no,resizable=no,location=no,status=no"
        );
    }
    copyFunc(copyContent) {
        if (navigator.clipboard) {
            // clipboard api 复制
            navigator.clipboard.writeText(copyContent);
        } else {
            var textarea = document.createElement('textarea');
            document.body.appendChild(textarea);
            // 隐藏此输入框
            textarea.style.position = 'fixed';
            textarea.style.clip = 'rect(0 0 0 0)';
            textarea.style.top = '10px';
            // 赋值
            textarea.value = copyContent;
            // 选中
            textarea.select();
            // 复制
            document.execCommand('copy', true);
            // 移除输入框
            document.body.removeChild(textarea);
        }
    }
    /**
     * 各社交平台分享插件调用
     * @param {string} type 社交平台
     */
     getSocialShareAPI(type) {
        let url = '';
        let pageTitle = document.querySelector("meta[property='og:title']").getAttribute("content")
        const updateTime = Date.now();
        const endShareUrl = `${this.pageShareUrl}?t=${updateTime}`
        switch (type) {
            case "Facebook":
                url = 'https://www.facebook.com/sharer.php?u=' + encodeURIComponent(endShareUrl);
                break;
            case "Twitter":
                url = `https://twitter.com/intent/tweet?original_referer=${encodeURIComponent(this.pageShareUrl)}&ref_src=${encodeURIComponent("twsrc^tfw|twcamp^buttonembed|twterm^share|twgr^")}&text=${encodeURIComponent(pageTitle)}&url=${encodeURIComponent(`${endShareUrl}`)}`;
                break;
            case "WhatsApp":
                url = `https://api.whatsapp.com/send?text=${encodeURIComponent(endShareUrl)}`;
                break;
            case "Line":
                url = `https://social-plugins.line.me/lineit/share?url=${encodeURIComponent(`${endShareUrl}`)}`;
                break;
            default:
                url = '';
                break;
        }
        return url;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    new StoriesShare()
})
